def home():
 out=head('RadioGenoma — Cuando un núcleo decae dentro del ADN humano','Atlas interactivo de Física Subatómica: yodo-125, yodo-131, electrones Auger, daño, reparación y mutaciones HPRT en células humanas.')+nav()
